"use client";

import React from "react";

interface HeaderProps {
  karanlikMod: boolean;
  toggleKaranlikMod: () => void;
  metinBoyutu: number;
  setMetinBoyutu: React.Dispatch<React.SetStateAction<number>>;
  tema: {
    yaziAna: string;
    yaziAlt: string;
    kenarlik: string;
  };
}

export default function Header({
  karanlikMod,
  toggleKaranlikMod,
  metinBoyutu,
  setMetinBoyutu,
  tema,
}: HeaderProps) {
  return (
    <header className="flex flex-col items-center justify-between pb-4 border-b gap-3" style={{ borderColor: tema.kenarlik }}>
      <div className="flex w-full items-center justify-between">
        {/* Başlık & Marka Metni */}
        <div>
          <h1 className="text-2xl font-bold tracking-tight" style={{ color: tema.yaziAna }}>
            Çerkesçe Sözlük
          </h1>
          <p className="mt-1 text-xs sm:text-sm font-medium" style={{ color: tema.yaziAlt }}>
            34 Sözlük • 428.679+ Kayıt • Açık Mektep Dijital Arşivi
          </p>
        </div>

        {/* Aksiyonlar (Tema & Metin Boyutu) */}
        <div className="flex items-center gap-2">
          <div className="flex items-center rounded-lg p-1 border" style={{ borderColor: tema.kenarlik }}>
            <button
              onClick={() => setMetinBoyutu((prev) => Math.max(12, prev - 2))}
              className="px-2 py-1 text-xs font-bold rounded hover:opacity-80"
              style={{ color: tema.yaziAna }}
              title="Metni Küçült"
            >
              A-
            </button>
            <span className="text-xs px-1" style={{ color: tema.yaziAlt }}>{metinBoyutu}px</span>
            <button
              onClick={() => setMetinBoyutu((prev) => Math.min(24, prev + 2))}
              className="px-2 py-1 text-xs font-bold rounded hover:opacity-80"
              style={{ color: tema.yaziAna }}
              title="Metni Büyüt"
            >
              A+
            </button>
          </div>

          <button
            onClick={toggleKaranlikMod}
            className="p-2 rounded-lg border text-sm font-semibold hover:opacity-80 transition-opacity"
            style={{ borderColor: tema.kenarlik, color: tema.yaziAna }}
            title="Karanlık Mod Değiştir"
          >
            {karanlikMod ? "☀️" : "🌙"}
          </button>
        </div>
      </div>
    </header>
  );
}